package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSetting {

    public static final String CLERK_LIMIT = "clerk-limit";

    public static final String FLOOR = "floor";

    public static final String TERMS = "terms";

    public static final String LATE_PCT = "late-pct";

    public static final String POLICY_DATE = "policy-date";

    public static final String PERIOD_NUMBERING_FROM = "period-numbering-from";

    /** A number of days: 0 or more, whole. */
    private static final Pattern DAYS = Pattern.compile("\\d{1,4}");

    /** A percent: 0 or more, with at most two decimals. */
    private static final Pattern PERCENT = Pattern.compile("\\d{1,3}(\\.\\d{1,2})?");

    /** An amount: 0 or more, with at most two decimals. */
    private static final Pattern AMOUNT = Pattern.compile("\\d{1,10}(\\.\\d{1,2})?");

    public void validate(@RequestBody SettingRequest request, Out<ValidSetting> body) throws InvalidSettingException {
        String key = request.key() == null ? "" : request.key().trim();
        if (!CLERK_LIMIT.equals(key) && !FLOOR.equals(key) && !TERMS.equals(key) && !LATE_PCT.equals(key)
                && !POLICY_DATE.equals(key) && !PERIOD_NUMBERING_FROM.equals(key)) {
            throw new InvalidSettingException("No such setting: " + key);
        }
        String raw = request.value() == null ? "" : request.value().trim();
        if (POLICY_DATE.equals(key)) {
            if (raw.isEmpty()) {
                body.set(new ValidSetting(key, null, request.user(), null)); // blank: the sheet's today
                return;
            }
            try {
                body.set(new ValidSetting(key, null, request.user(), LocalDate.parse(raw)));
            } catch (DateTimeParseException e) {
                throw new InvalidSettingException("The policy date must be a date (YYYY-MM-DD), or blank for the sheet's today");
            }
            return;
        }
        if (PERIOD_NUMBERING_FROM.equals(key)) {
            if (raw.isEmpty()) {
                body.set(new ValidSetting(key, null, request.user(), null)); // blank: off
                return;
            }
            try {
                body.set(new ValidSetting(key, null, request.user(), LocalDate.parse(raw)));
            } catch (DateTimeParseException e) {
                throw new InvalidSettingException("The period numbering from must be a date (YYYY-MM-DD), or blank for off");
            }
            return;
        }
        if (TERMS.equals(key)) {
            if (!DAYS.matcher(raw).matches()) {
                throw new InvalidSettingException("The terms must be a whole number of days, 0 or more");
            }
            body.set(new ValidSetting(key, new BigDecimal(Integer.parseInt(raw)), request.user()));
            return;
        }
        if (LATE_PCT.equals(key)) {
            if (!PERCENT.matcher(raw).matches()) {
                throw new InvalidSettingException("The late percent must be a percent of 0.00 or more with at most two decimals");
            }
            body.set(new ValidSetting(key, new BigDecimal(raw).setScale(2), request.user()));
            return;
        }
        if (FLOOR.equals(key)) {
            if (!AMOUNT.matcher(raw).matches()) {
                throw new InvalidSettingException("The floor must be an amount of 0.00 or more with at most two decimals");
            }
            body.set(new ValidSetting(key, new BigDecimal(raw).setScale(2), request.user()));
            return;
        }
        if (raw.isEmpty()) {
            body.set(new ValidSetting(key, null, request.user())); // blank: no limit
            return;
        }
        if (!AMOUNT.matcher(raw).matches()) {
            throw new InvalidSettingException("The clerk limit must be an amount of 0.00 or more with at most two decimals");
        }
        body.set(new ValidSetting(key, new BigDecimal(raw).setScale(2), request.user()));
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class SaveSetting {
    public void save(@PathVariable("sheetId") String sheetId, @Val ValidSetting setting, @Val RollupFigures before,
            Settings settings, Rollup rollup, Audit audit, ObjectResponse<SettingsResponse> response) {
        if (ValidateSetting.POLICY_DATE.equals(setting.key())
                || ValidateSetting.PERIOD_NUMBERING_FROM.equals(setting.key())) {
            if (ValidateSetting.POLICY_DATE.equals(setting.key())) {
                settings.setPolicyDate(sheetId, setting.date());
            } else {
                settings.setPeriodNumberingFrom(sheetId, setting.date());
            }
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                    + " key=" + setting.key() + " value=" + (setting.date() == null ? "" : setting.date().toString()));
            rollup.recordChanges(sheetId, setting.user(), before);
            response.send(settings.load(sheetId));
            return;
        }
        if (ValidateSetting.FLOOR.equals(setting.key())) {
            settings.setFloor(sheetId, setting.value());
        } else if (ValidateSetting.LATE_PCT.equals(setting.key())) {
            settings.setLatePct(sheetId, setting.value());
        } else if (ValidateSetting.TERMS.equals(setting.key())) {
            settings.setTerms(sheetId, setting.value().intValueExact());
        } else {
            settings.setClerkLimit(sheetId, setting.value());
        }
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                + " key=" + setting.key() + " value=" + (setting.value() == null ? "" : setting.value().toPlainString()));
        rollup.recordChanges(sheetId, setting.user(), before);
        response.send(settings.load(sheetId));
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.sheet.Sheets;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The settings store: the sheet's clerk limit, its floor, its terms, its late percent, its policy date, its period numbering from and the role each user name holds on it. */
@Repository
public class Settings {

    public static final String CLERK = "clerk";

    public static final String STEWARD = "steward";

    private final JdbcTemplate jdbc;

    private final Sheets sheets;

    public Settings(JdbcTemplate jdbc, Sheets sheets) {
        this.jdbc = jdbc;
        this.sheets = sheets;
    }

    /** The sheet's clerk limit; null for no limit. */
    public BigDecimal clerkLimit(String sheetId) {
        sheets.today(sheetId); // the sheet's row holds the limit
        return jdbc.queryForObject("SELECT clerk_limit FROM sheet WHERE id = ?", BigDecimal.class, sheetId);
    }

    public void setClerkLimit(String sheetId, BigDecimal limit) {
        sheets.today(sheetId);
        jdbc.update("UPDATE sheet SET clerk_limit = ? WHERE id = ?", limit, sheetId);
    }

    /** The sheet's floor: a claim's live due is at least it. */
    public BigDecimal floor(String sheetId) {
        sheets.today(sheetId); // the sheet's row holds the floor
        return jdbc.queryForObject("SELECT due_floor FROM sheet WHERE id = ?", BigDecimal.class, sheetId);
    }

    public void setFloor(String sheetId, BigDecimal floor) {
        sheets.today(sheetId);
        jdbc.update("UPDATE sheet SET due_floor = ? WHERE id = ?", floor, sheetId);
    }

    /** The sheet's terms in days: a claim's due-by is its date plus them. */
    public int terms(String sheetId) {
        sheets.today(sheetId); // the sheet's row holds the terms
        return jdbc.queryForObject("SELECT terms_days FROM sheet WHERE id = ?", Integer.class, sheetId);
    }

    public void setTerms(String sheetId, int days) {
        sheets.today(sheetId);
        jdbc.update("UPDATE sheet SET terms_days = ? WHERE id = ?", days, sheetId);
    }

    /** The sheet's late percent: an overdue claim gains it of its figure for every full 30 days overdue. */
    public BigDecimal latePct(String sheetId) {
        sheets.today(sheetId); // the sheet's row holds the late percent
        return jdbc.queryForObject("SELECT late_pct FROM sheet WHERE id = ?", BigDecimal.class, sheetId);
    }

    public void setLatePct(String sheetId, BigDecimal pct) {
        sheets.today(sheetId);
        jdbc.update("UPDATE sheet SET late_pct = ? WHERE id = ?", pct, sheetId);
    }

    /** The sheet's policy date as set; null when blank. */
    public LocalDate policyDateSet(String sheetId) {
        sheets.today(sheetId); // the sheet's row holds the policy date
        Date date = jdbc.queryForObject("SELECT policy_date FROM sheet WHERE id = ?", Date.class, sheetId);
        return date == null ? null : date.toLocalDate();
    }

    /** The sheet's policy date: a claim dated before it rounds half up, on or after it half to even.
     *  When blank it is the sheet's today. */
    public LocalDate policyDate(String sheetId) {
        LocalDate set = policyDateSet(sheetId);
        return set != null ? set : sheets.today(sheetId);
    }

    public void setPolicyDate(String sheetId, LocalDate date) {
        sheets.today(sheetId);
        jdbc.update("UPDATE sheet SET policy_date = ? WHERE id = ?", date == null ? null : Date.valueOf(date), sheetId);
    }

    /** The date from which claims opened are numbered within their period; null when off. */
    public LocalDate periodNumberingFrom(String sheetId) {
        sheets.today(sheetId); // the sheet's row holds the date
        Date date = jdbc.queryForObject("SELECT period_numbering_from FROM sheet WHERE id = ?", Date.class, sheetId);
        return date == null ? null : date.toLocalDate();
    }

    public void setPeriodNumberingFrom(String sheetId, LocalDate date) {
        sheets.today(sheetId);
        jdbc.update("UPDATE sheet SET period_numbering_from = ? WHERE id = ?", date == null ? null : Date.valueOf(date), sheetId);
    }

    /** The role the user name holds on the sheet; a clerk unless set otherwise. */
    public String role(String sheetId, String user) {
        List<String> found = jdbc.query("SELECT role FROM sheet_role WHERE sheet_id = ? AND user_name = ?",
                (rs, i) -> rs.getString(1), sheetId, user == null ? "" : user.trim());
        return found.isEmpty() ? CLERK : found.get(0);
    }

    public void setRole(String sheetId, String user, String role) {
        jdbc.update("MERGE INTO sheet_role (sheet_id, user_name, role) KEY (sheet_id, user_name) VALUES (?, ?, ?)",
                sheetId, user, role);
    }

    /** The sheet's settings as shown: the clerk limit ("" for none), the floor, the terms, the late percent, the policy date ("" for blank), the period numbering from ("" for off) and every role set, by user name. */
    public SettingsResponse load(String sheetId) {
        BigDecimal limit = clerkLimit(sheetId);
        LocalDate policy = policyDateSet(sheetId);
        LocalDate numbering = periodNumberingFrom(sheetId);
        List<RoleResponse> roles = jdbc.query(
                "SELECT user_name, role FROM sheet_role WHERE sheet_id = ? ORDER BY user_name",
                (rs, i) -> new RoleResponse(rs.getString(1), rs.getString(2)), sheetId);
        return new SettingsResponse(limit == null ? "" : limit.setScale(2).toPlainString(),
                floor(sheetId).setScale(2).toPlainString(), String.valueOf(terms(sheetId)),
                latePct(sheetId).setScale(2).toPlainString(), policy == null ? "" : policy.toString(),
                numbering == null ? "" : numbering.toString(), roles);
    }
}
